import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'package:file_selector/file_selector.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
void main(){WidgetsFlutterBinding.ensureInitialized();runApp(const SnipApp());}
class SnipApp extends StatelessWidget {const SnipApp({super.key});@override Widget build(BuildContext context)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Snip & Extract',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff5266dc)),useMaterial3:true),home:const SnipHome());}
class SnipHome extends StatefulWidget {const SnipHome({super.key});@override State<SnipHome> createState()=>_SnipHomeState();}
class _SnipHomeState extends State<SnipHome>{Uint8List? image;String status='Select a screen area to begin';bool busy=false;final textController=TextEditingController();
Future<Map<String,dynamic>> invoke(String action,[Map<String,dynamic>? data]) async {final p=await Process.run('powershell.exe',['-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File','${File(Platform.resolvedExecutable).parent.path}\\snip_native.ps1','-Action',action,if(data!=null)...['-Payload',base64Encode(utf8.encode(jsonEncode(data)))] ]);if(p.exitCode!=0)throw Exception(p.stderr.toString().trim().isEmpty?p.stdout:p.stderr);return Map<String,dynamic>.from(jsonDecode(p.stdout.toString().trim()));}
Future<void> capture() async {setState((){busy=true;status='Drag to select area; Esc to cancel';});try{final r=await invoke('capture');if(r['cancelled']==true){setState(()=>status='Capture cancelled');return;}setState((){image=base64Decode(r['image'] as String);textController.clear();status='Captured ${r['width']} × ${r['height']} pixels';});}catch(e){setState(()=>status='Capture failed: $e');}finally{if(mounted)setState(()=>busy=false);}}
Future<void> save() async {if(image==null)return;final f=await getSaveLocation(suggestedName:'Snip_${DateTime.now().millisecondsSinceEpoch}.png',acceptedTypeGroups:[const XTypeGroup(label:'PNG',extensions:['png'])]);if(f==null)return;try{await File(f.path).writeAsBytes(image!);setState(()=>status='Saved to ${f.path}');}catch(e){setState(()=>status='Save failed: $e');}}
Future<void> copyImage() async {if(image==null)return;setState(()=>busy=true);try{await invoke('copyImage',{'image':base64Encode(image!)});setState(()=>status='Image copied');}catch(e){setState(()=>status='Image copy failed: $e');}finally{if(mounted)setState(()=>busy=false);}}
Future<void> ocr() async {if(image==null)return;setState((){busy=true;status='Recognising text offline…';});try{final r=await invoke('ocr',{'image':base64Encode(image!)});setState((){textController.text=(r['text']??'').toString();status=textController.text.trim().isEmpty?'No text detected':'Text extracted';});}catch(e){setState(()=>status='OCR failed: $e');}finally{if(mounted)setState(()=>busy=false);}}
Future<void> copyText() async {if(textController.text.trim().isEmpty)return;await Clipboard.setData(ClipboardData(text:textController.text));setState(()=>status='Text copied');}
@override void dispose(){textController.dispose();super.dispose();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Snip & Extract')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Wrap(spacing:9,runSpacing:9,children:[FilledButton.icon(onPressed:busy?null:capture,icon:const Icon(Icons.crop_free),label:const Text('New Snip')),OutlinedButton.icon(onPressed:busy||image==null?null:save,icon:const Icon(Icons.save_alt),label:const Text('Save PNG')),OutlinedButton.icon(onPressed:busy||image==null?null:copyImage,icon:const Icon(Icons.copy_all),label:const Text('Copy Image')),OutlinedButton.icon(onPressed:busy||image==null?null:ocr,icon:const Icon(Icons.document_scanner_outlined),label:const Text('Extract Text'))]),const SizedBox(height:12),Text(status),const SizedBox(height:12),Expanded(flex:3,child:Container(color:const Color(0xfff1f2f5),child:image==null?const Center(child:Text('Screenshot preview')):InteractiveViewer(child:Center(child:Image.memory(image!,fit:BoxFit.contain))))),const SizedBox(height:12),Row(children:[const Text('Extracted Text',style:TextStyle(fontWeight:FontWeight.bold)),const Spacer(),TextButton.icon(onPressed:textController.text.trim().isEmpty?null:copyText,icon:const Icon(Icons.copy),label:const Text('Copy Text'))]),Expanded(flex:2,child:TextField(controller:textController,maxLines:null,expands:true,textAlignVertical:TextAlignVertical.top,decoration:const InputDecoration(border:OutlineInputBorder(),hintText:'Extracted text appears here'),onChanged:(_)=>setState((){})))])));
}
